def gen(rng):
    LO, HI = -2**31, 2**31 - 1
    def fmt(ps):
        return str(len(ps)) + '\n' + '\n'.join(f'{a} {b}' for a, b in ps)
    tests = [
        fmt([(0, 0)]),
        fmt([(1, 2)]),
        fmt([(2, 1)]),
        fmt([(LO, HI), (HI, LO), (LO, LO), (HI, HI)]),
        fmt([(-1, 0), (0, -1), (-5, -3), (-3, -5), (7, 7), (-7, -7)]),
        fmt([(LO, 0), (0, LO), (HI, 0), (0, HI), (LO, -1), (HI, -1)]),
    ]
    for n in (3, 8, 15, 20):
        for _ in range(3):
            tests.append(fmt([(rng.randint(-50, 50), rng.randint(-50, 50)) for _ in range(n)]))
    for _ in range(3):
        tests.append(fmt([(rng.randint(LO, HI), rng.randint(LO, HI)) for _ in range(20)]))
    tests.append(fmt([(rng.randint(LO, HI), rng.randint(LO, HI)) for _ in range(50000)]))
    tests.append(fmt([(rng.choice([LO, HI, 0, -1, 1]), rng.choice([LO, HI, 0, -1, 1])) for _ in range(50000)]))
    tests.append(fmt([(rng.randint(-1000, 1000), rng.randint(-1000, 1000)) for _ in range(50000)]))
    return tests

